def file_name_check(file_name):
    # Check if there are more than three digits
    if len(file_name) > 3:
        return 'No'

    # Check if there is exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Check if the part before the dot starts with a letter
    if not file_name.split('.')[0].isalpha():
        return 'No'

    # Check if the part after the dot is one of the valid extensions
    if file_name.split('.')[1].lower() not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'
